        _traceMode = false;
        _traceCorrelationId = null;
        _sandboxMode = false;
        _sandboxSequence = null;
        _stepMode = false;
        _stepSequence = null;
        _bisectMode = false;
        _bisectGood = null;
        _bisectBad = null;
        _blameMode = false;
